import html
import re

import charset_normalizer
from requests.utils import _parse_content_type_header

TITLE_RE = re.compile(r"<title[^>]*>(.*?)</title>", re.IGNORECASE | re.DOTALL)


def detect_encoding(resp):
    _, params = _parse_content_type_header(resp.headers.get("Content-Type", ""))
    charset = params.get("charset")
    if charset and charset is not True:
        return charset
    result = charset_normalizer.from_bytes(resp.content).best()
    return result.encoding if result else "utf-8"


def page_title(resp):
    if not resp.content:
        return ""
    text = resp.content.decode(detect_encoding(resp), errors="replace")
    match = TITLE_RE.search(text)
    if not match:
        return ""
    return html.unescape(" ".join(match.group(1).split()))

from typing import List

import tomllib
from pydantic import BaseModel, validator


class Site(BaseModel):
    name: str
    url: str

    class Config:
        anystr_strip_whitespace = True

    @validator("name")
    def name_not_empty(cls, value):
        if not value:
            raise ValueError("site name can not be empty")
        return value

    @validator("url")
    def url_has_scheme(cls, value):
        if not value.startswith(("http://", "https://")):
            raise ValueError("url must start with http:// or https://")
        return value


class Settings(BaseModel):
    title: str = "linkwatch"
    output: str = "status.html"
    sites: List[Site] = []

    class Config:
        extra = "forbid"


def load_settings(path="sites.toml"):
    with open(path, "rb") as f:
        data = tomllib.load(f)
    return Settings(**data)

import json
import os

from platformdirs import user_cache_dir

RESULTS_FILE = "results.json"


def cache_dir():
    path = os.environ.get("LINKWATCH_CACHE_DIR") or user_cache_dir("linkwatch")
    os.makedirs(path, exist_ok=True)
    return path


def cache_file():
    return os.path.join(cache_dir(), RESULTS_FILE)


def save_results(results):
    path = cache_file()
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(results, fh, indent=2)
    return path


def load_results():
    path = cache_file()
    if not os.path.exists(path):
        return []
    with open(path, encoding="utf-8") as fh:
        return json.load(fh)

